// Differential checks of PrimOpChar01-faithful.js against Lean, generated by leanscript --check
import * as M from "./PrimOpChar01-faithful.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test1(\"a\", \"a\")", () => M.test1("a", "a"), "true", false);
check("test1(\"a\", \"z\")", () => M.test1("a", "z"), "false", false);
check("test1(\"z\", \"a\")", () => M.test1("z", "a"), "false", false);
check("test1(\"a\", \" \")", () => M.test1("a", " "), "false", false);
check("test1(\"z\", \"z\")", () => M.test1("z", "z"), "true", false);
check("test1(\" \", \"a\")", () => M.test1(" ", "a"), "false", false);
check("test1(\"a\", \"é\")", () => M.test1("a", "é"), "false", false);
check("test1(\"z\", \" \")", () => M.test1("z", " "), "false", false);
check("test1(\" \", \"z\")", () => M.test1(" ", "z"), "false", false);
check("test1(\"é\", \"a\")", () => M.test1("é", "a"), "false", false);
check("test1(\"z\", \"é\")", () => M.test1("z", "é"), "false", false);
check("test1(\" \", \" \")", () => M.test1(" ", " "), "true", false);
check("test1(\"é\", \"z\")", () => M.test1("é", "z"), "false", false);
check("test1(\" \", \"é\")", () => M.test1(" ", "é"), "false", false);
check("test1(\"é\", \" \")", () => M.test1("é", " "), "false", false);
check("test1(\"é\", \"é\")", () => M.test1("é", "é"), "true", false);
check("test2(\"a\", \"a\")", () => M.test2("a", "a"), "false", false);
check("test2(\"a\", \"z\")", () => M.test2("a", "z"), "true", false);
check("test2(\"z\", \"a\")", () => M.test2("z", "a"), "true", false);
check("test2(\"a\", \" \")", () => M.test2("a", " "), "true", false);
check("test2(\"z\", \"z\")", () => M.test2("z", "z"), "false", false);
check("test2(\" \", \"a\")", () => M.test2(" ", "a"), "true", false);
check("test2(\"a\", \"é\")", () => M.test2("a", "é"), "true", false);
check("test2(\"z\", \" \")", () => M.test2("z", " "), "true", false);
check("test2(\" \", \"z\")", () => M.test2(" ", "z"), "true", false);
check("test2(\"é\", \"a\")", () => M.test2("é", "a"), "true", false);
check("test2(\"z\", \"é\")", () => M.test2("z", "é"), "true", false);
check("test2(\" \", \" \")", () => M.test2(" ", " "), "false", false);
check("test2(\"é\", \"z\")", () => M.test2("é", "z"), "true", false);
check("test2(\" \", \"é\")", () => M.test2(" ", "é"), "true", false);
check("test2(\"é\", \" \")", () => M.test2("é", " "), "true", false);
check("test2(\"é\", \"é\")", () => M.test2("é", "é"), "false", false);

console.log(`PrimOpChar01-faithful.js: ${passed} passed, ${failed} failed`);
